INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q4594811', '1999 Ivorian coup d''état', 'The 1999 Ivorian coup d''état took place on 24 December 1999. It was the first coup d''état since the independence of Ivory Coast and led to the removal of president Henri Konan Bédié.', 1999, 12, 24, NULL, NULL, NULL, 'day', '24 December 1999', 30, 'https://en.wikipedia.org/wiki/1999_Ivorian_coup_d''%C3%A9tat'),
  ('Q1153249', 'Kenya Airways Flight 431', 'Kenya Airways Flight 431 was an international scheduled Abidjan–Lagos–Nairobi passenger service, operated by Kenyan national airline Kenya Airways. On 30 January 2000, the Airbus A310 serving the flight crashed into the sea off the Ivory Coast, shortly after takeoff at night from Félix-Houphouët-Boigny International Airport, Abidjan.', 2000, 1, 30, NULL, NULL, NULL, 'day', '30 January 2000', 55, 'https://en.wikipedia.org/wiki/Kenya_Airways_Flight_431'),
  ('Q1021175', 'First Ivorian Civil War', 'The First Ivorian Civil War was a civil conflict in the Ivory Coast (Côte d''Ivoire) that began with a military rebellion on 19 September 2002 and ended with a peace agreement on 4 March 2007. The conflict pitted the government of Ivorian President Laurent Gbagbo against a domestic insurgency led by the New Forces of Ivory Coast (Forces nouvelles de Côte d''Ivoire).', 2002, 9, 19, 2007, 3, 4, 'day', '19 September 2002 – 4 March 2007', 61, 'https://en.wikipedia.org/wiki/First_Ivorian_Civil_War'),
  ('Q2858679', '2004 French–Ivorian clashes', 'In 2004, an armed conflict took place between French and Côte d''Ivoire forces. On 6 November 2004, two Ivorian Air force Su-25 attack fighters launched an air attack on French peacekeepers in the northern part of Côte d''Ivoire who were stationed there as part of Opération Licorne (Unicorn), the French military operation in support of the United Nations Operation in Côte d''Ivoire (UNOCI).', 2004, 11, 6, NULL, NULL, NULL, 'day', '6 November 2004', 43, 'https://en.wikipedia.org/wiki/2004_French%E2%80%93Ivorian_clashes'),
  ('Q909819', '2010–2011 Ivorian crisis', 'The 2010–11 Ivorian crisis was a political crisis in Ivory Coast which began after Laurent Gbagbo, the President of Ivory Coast since 2000, was proclaimed the winner of the Ivorian election of 2010, the first election in the country in 10 years. The opposition candidate, Alassane Ouattara, and a number of countries, organisations and leaders worldwide claimed Ouattara had won the election.', 2010, 11, 28, 2011, 4, 11, 'day', '28 November 2010 – 11 April 2011', 53, 'https://en.wikipedia.org/wiki/2010%E2%80%932011_Ivorian_crisis'),
  ('Q1087909', 'Second Ivorian Civil War', 'The Second Ivorian Civil War broke out in March 2011 when the crisis in Ivory Coast escalated into full-scale military conflict between forces loyal to Laurent Gbagbo, the President of Ivory Coast since 2000, and supporters of the internationally recognised president-elect Alassane Ouattara. After months of unsuccessful negotiations and sporadic violence between supporters of the two sides, the crisis entered a critical stage as Ouattara''s forces seized control of most of the country with the help of the UN, with Gbagbo entrenched in Abidjan, the country''s largest city.', 2010, 11, 28, 2011, 4, 11, 'day', '28 November 2010 – 11 April 2011', 52, 'https://en.wikipedia.org/wiki/Second_Ivorian_Civil_War'),
  ('Q23045756', '2016 Grand-Bassam shootings', 'On 13 March 2016, three Islamist gunmen opened fire at a beach resort in Grand-Bassam, Ivory Coast, killing at least 19 people and injuring 33 others.', 2016, 3, 13, NULL, NULL, NULL, 'day', '13 March 2016', 52, 'https://en.wikipedia.org/wiki/Grand-Bassam_shootings');

